package com.ray.controller;
import com.ray.result.*;import com.ray.service.VoucherRedemptionService;import com.ray.utils.converter.IdUtils;import com.ray.vo.*;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/admin/redemptions") @SecurityRequirement(name="BearerAuth") @Tag(name="管理端核销审计")
public class AdminRedemptionController {private final VoucherRedemptionService service;public AdminRedemptionController(VoucherRedemptionService service){this.service=service;}@GetMapping @Operation(summary="查询核销审计",operationId="listAdminRedemptions")public Result<PageResult<VoucherRedemptionVO>> list(@RequestParam(defaultValue="1") @Min(1)int page,@RequestParam(defaultValue="20") @Min(1) @Max(100)int size){return Result.ok(service.list(page,size,true));}@GetMapping("/{id}") @Operation(summary="核销审计详情",operationId="getAdminRedemption")public Result<VoucherRedemptionVO> get(@PathVariable String id){return Result.ok(service.get(IdUtils.parse(id,"redemptionId"),true));}}
